#!/data/data/com.termux/files/usr/bin/bash
# apply_all40.sh - اللغة الفرنسية للأولى ثانوي: الجزء 1 = 25 بطاقة + الخرائط الذهنية (زر 🗺️)
# لا يمسّ مفتاح الترخيص: يضيف ملفات جديدة ووسوم script فقط في index.html بعد نسخة احتياطية.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f index.html.bak_fr1 ] || cp index.html index.html.bak_fr1

# --- اكتشاف مفتاح مادة اللغة الفرنسية في الأولى ثانوي (كل الشعب) من db.js ---
CH=$(tr -d '\n' < db.js | sed 's/"AS1": *{"name"/\n&/' | tail -1 | sed 's/"AS2": *{"name".*//')
KF=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"[^"]*الفرنسية[^"]*"' | sed 's/"key": *"\([^"]*\)".*/\1/' | sort -u)
if [ -z "$KF" ]; then
  printf '%s' "$CH" | head -c 4000 > ~/storage/downloads/fr1_diag.txt
  echo "لم أجد مادة اللغة الفرنسية للأولى ثانوي في db.js. كتبتُ تشخيصا في التنزيلات: fr1_diag.txt - أرسله لي."
  echo "لم يُغيَّر شيء."
  exit 1
fi
JF=$(printf '%s\n' $KF | sed 's/.*/"&"/' | paste -sd, | sed 's/^/[/;s/$/]/')
echo "مفاتيح اللغة الفرنسية: $JF"

cat > fr1_data.js <<'ZAD_EOF'
