[{"m": 1, "i": "🔬", "t": "La vulgarisation scientifique : définition et visée", "B": [["التعريف", ["La vulgarisation scientifique : rendre accessible au grand public un savoir scientifique", "Rostand : «rapprocher l'homme de l'homme en réduisant l'ignorance»"]], ["La visée (الغاية)", ["Informer : donner des informations sur un sujet", "Expliquer : répondre à une interrogation du destinataire (pourquoi ? comment ?)"]], ["Caractéristiques", ["Vocabulaire du thème (champ lexical) + définitions et exemples", "Structure : logique, chronologique ou énumérative", "Constructions impersonnelles pour objectiver le discours"]]], "K": "Un texte de vulgarisation a pour visée d'informer ou d'expliquer.", "M": ["Projet 1 : réaliser une campagne d'information pour les élèves du lycée", "Visée = intention du scripteur"], "X": "هو نص يبسّط العلم للقارئ العادي: يعطيه معلومة (informer) أو يجيبه عن سؤال (expliquer).", "EX": [["Quelle est la visée d'un texte de vulgarisation scientifique ?", "Informer ou expliquer : donner des connaissances à un lecteur non spécialiste."], ["Dans le second cas (expliquer), que suppose le scripteur chez le destinataire ?", "Une interrogation (pourquoi ? comment ?) à laquelle il est capable de répondre."]], "n": 1, "s": "f", "k": "f1"}, {"m": 1, "i": "🔍", "t": "Observation : le paratexte et la situation de communication", "B": [["Le paratexte", ["Tout ce qui entoure le texte : titre, sous-titre, source (références), date, images, mise en page", "Il permet d'émettre des hypothèses sur le contenu et le type du texte"]], ["Situation de communication", ["Qui ? (scripteur / destinataire)", "Quoi ? (thème)  |  Comment ? (type de document, genre)", "Où ? Quand ? (indices spatio-temporels)"]], ["Exemples du manuel", ["Texte p.7 : article de presse (JA/L'Intelligent, 2004) sur les langues africaines + carte", "Le scripteur = celui qui écrit le texte (ici un journaliste)"]]], "K": "On observe d'abord le paratexte sans lire le texte pour formuler des hypothèses.", "M": ["Document iconique : image, carte, schéma, tableau accompagnant le texte", "Références : auteur, titre de l'ouvrage, éditeur, date"], "X": "قبل قراءة النص، انظر إلى العنوان والمصدر والصورة: تفهم نوع النص وغايته.", "EX": [["Citez trois éléments du paratexte.", "Le titre, les références (auteur, source, date), les images/cartes, la mise en page."], ["Que signifie «scripteur» ?", "Celui qui écrit le texte (l'auteur ou le journaliste)."]], "n": 2, "s": "f", "k": "f1"}, {"m": 1, "i": "📄", "t": "Le paragraphe, l'alinéa et les unités de signification", "B": [["Le paragraphe", ["Partie du discours ayant une cohérence sémantique : on peut lui trouver un titre", "Présentation typographique : premier mot en retrait + retour à la ligne à la fin"]], ["L'alinéa", ["Paragraphe très court, parfois une seule phrase", "Plusieurs alinéas peuvent se rattacher à une même idée : petites unités qui forment une grande unité"]], ["Savoir-faire (pour le résumé)", ["Dégager la grande unité de signification de chaque paragraphe", "Regrouper les paragraphes en ensembles plus grands et leur donner un titre"]]], "K": "Chaque paragraphe a une idée principale résumée par un titre.", "M": ["Titre du paragraphe = résumé de son idée", "Faire le plan du texte = titres de chaque partie"], "X": "الفقرة وحدة معنى: لكل فقرة فكرة كبرى تلخّصها بعنوان، وهذا أساس التلخيص.", "EX": [["Comment reconnaît-on un paragraphe ?", "Par sa présentation (retrait du premier mot, retour à la ligne) et par sa cohérence de sens."], ["Qu'est-ce qu'un alinéa ?", "Un paragraphe très court (parfois une phrase) qui peut se rattacher à une idée plus grande."]], "n": 3, "s": "f", "k": "f1"}, {"m": 1, "i": "🗣️", "t": "Le scripteur et les marques de l'énonciation", "B": [["Qui écrit ?", ["Même dans un texte de vulgarisation (informer/expliquer), le scripteur peut laisser des traces de sa présence", "Un texte « objectif » efface presque toutes ces marques"]], ["Les marques", ["Tournures syntaxiques : «Il est clair…», «Il est intéressant de constater…»", "Vocabulaire mélioratif ou péjoratif (jugement) : «un pas d'une extrême importance»", "Pronoms : je / nous / vous ; adverbes et modalisateurs : «Il semble que…», «Nous sommes amenés à croire…»"]], ["Effet", ["On peut se faire une idée de la personnalité, des opinions, des intentions du scripteur", "Les marques d'énonciation sont à supprimer dans un résumé"]]], "K": "Les marques d'énonciation révèlent la présence et l'opinion du scripteur.", "M": ["Certitude : «Il est clair que…» ; hypothèse : «Il semble que…»", "Résumé objectif : pas de «je», pas de jugement"], "X": "ابحث عن آثار الكاتب في النص: ضمائر، أحكام، عبارات الشك واليقين؛ وأزِلها عند التلخيص.", "EX": [["Les expressions «Il semble enfin que…» et «C'est en tout cas…» expriment-elles la même certitude ?", "Non : «Il semble» exprime une hypothèse (incertitude), «C'est en tout cas» exprime une certitude."], ["Donnez deux marques de la présence du scripteur.", "Un adjectif mélioratif (ex. «un pas d'une extrême importance»), un pronom («nous»), une tournure comme «Il est intéressant de constater…»."]], "n": 4, "s": "f", "k": "f1"}, {"m": 1, "i": "📍", "t": "La situation d'énonciation : oral et écrit", "B": [["Définition", ["Ensemble des facteurs qui déterminent la production d'un discours", "Nombre et personnalité des participants : je/nous, tu/vous", "Indices spatio-temporels : ici, maintenant, ce, aujourd'hui", "Marques de jugement"]], ["Les deux discours p.14", ["Texte 1 (oral transcrit) : langue familière, ponctuation absente, «tu» (destinataire présent), «ce soir», «ce livre»", "Texte 2 (écrit préparé) : langue soutenue, 3e personne/«vous», phrases construites"]], ["Oral vs écrit", ["Même code, mais situation de communication différente", "L'oral : moins précis, avec accentuation, intonation, débit", "L'écrit traduit ces moyens par des mots et la ponctuation"]]], "K": "Oral et écrit font partie du même code mais diffèrent par la situation de communication.", "M": ["Texte oral sans préparation : phrases courtes, répétitions, «heu…», «tiens !»", "Démonstratif «ce» lié à la situation : «ce livre» (celui qu'on voit)"], "X": "نفس اللغة، لكن الكلام الشفوي مرتبط بالموقف (أنا/أنت/هنا/الآن) والمكتوب أدق وأطول.", "EX": [["Donnez deux marques de la langue familière dans le discours oral p.14.", "«com'nous», «t'es trop p'tit», «il a pas…», «tu piges pas», «j'vois», «c'qu'on sait»."], ["Quelle est la visée commune aux deux discours ?", "Expliquer comment s'est constitué le français (question à l'origine : d'où vient la langue française ?)."]], "n": 5, "s": "f", "k": "f1"}, {"m": 1, "i": "🔗", "t": "Articulateurs, champ lexical et champ sémantique", "B": [["Les articulateurs", ["Mots qui organisent le texte (ou les phrases) et expriment un rapport logique", "Ex. : d'abord, ensuite, enfin (chronologie) ; mais, cependant, toutefois (opposition) ; car, parce que (cause) ; donc, aussi (conséquence)"]], ["Champ lexical", ["Ensemble des mots qui renvoient à une même idée, à un même thème à l'intérieur d'un texte", "Ex. : champ lexical de l'eau : fleuve, rivière, source, delta, lac…"]], ["Champ sémantique", ["Ensemble des sens que peut prendre un mot donné", "Pour le retrouver : se reporter au dictionnaire (ex. «champ» : champ de blé, champ de bataille, champ visuel…)"]]], "K": "Champ lexical = mots d'un même thème dans un texte ; champ sémantique = sens possibles d'un mot.", "M": ["Pour résumer, il faut repérer les articulateurs qui structurent le texte", "Le résumé suit l'ordre de présentation des idées"], "X": "الحقل المعجمي: كلمات النص حول موضوع واحد. الحقل الدلالي: معاني الكلمة الواحدة في القاموس.", "EX": [["Distinguez «champ lexical» et «champ sémantique».", "Le champ lexical regroupe les mots d'un même thème dans un texte ; le champ sémantique regroupe les différents sens d'un seul mot."], ["Relevez le champ lexical de l'eau : «Le Rhône tombe des Alpes… lac… mer… rivières… delta».", "Fleuve, lac, mer, rivières, torrent, source, delta, navigation, eau."]], "n": 6, "s": "f", "k": "f1"}, {"m": 1, "i": "🖼️", "t": "Le langage de l'image : cadrage, retouche, légende", "B": [["Idée générale", ["L'image, preuve apparemment tangible de la réalité, est souvent trompeuse", "On peut lui faire dire le contraire de la vérité"]], ["Trois techniques", ["Le cadrage : mise en valeur d'une partie du cliché, en éliminant le reste on change la signification", "La retouche : transformer un visage, éliminer l'arrière-plan, «détourer» une silhouette", "La légende : avec l'article, elle donne son sens à l'image"]], ["Rôle de l'image de presse", ["N'est pas un accessoire : information autant qu'illustration", "S'adresse à la sensibilité (choc psychologique) alors que l'écrit s'adresse à la raison"]], ["Exemples du manuel", ["Même photo du champion : «après l'exploit» / «la chute du champion»", "L'éléphant retouché sur deux décors", "Viansson-Ponté : la poursuite qui devient une course à l'autobus"]]], "K": "Cadrage, retouche et légende peuvent faire mentir une photographie.", "M": ["Texte : Yves Agues & J.-M. Croissandeau, Lire le journal (1979)", "Procédé d'énumération : tirets, puis nombres, adverbes (d'abord, ensuite…)"], "X": "الصورة قد تكذب: بالقصّ (cadrage) والتعديل (retouche) والتعليق (légende).", "EX": [["Citez les trois techniques de traitement de la photographie.", "Le cadrage, la retouche et la légende."], ["Pourquoi dit-on que l'image s'adresse à la sensibilité ?", "Parce qu'elle provoque un choc psychologique, alors que l'écrit s'adresse surtout à la raison."]], "n": 7, "s": "f", "k": "f1"}, {"m": 1, "i": "📡", "t": "La communication et le «bruit» (Vanoye)", "B": [["Idée", ["Toute communication a pour but la transmission d'un message", "Types : oral (voix, téléphone), écrit, gestes, code Morse, affiches, messages radio/TV"]], ["Le bruit", ["Tout ce qui affecte, à des degrés divers, la transmission du message", "Pas seulement sonore : une tache sur une feuille, une faute de frappe sont des bruits"]], ["Origines du bruit", ["Le canal (parasites)", "L'émetteur ou le récepteur (manque d'attention)", "Le message (insuffisamment clair)", "Le code (mal adapté au message)"]]], "K": "Le bruit est tout ce qui perturbe la transmission d'un message.", "M": ["Émetteur → message → canal → récepteur (avec un code)", "Évaluation formative p.22 : résumer le texte par suppression du non-indispensable"], "X": "الضجيج (bruit) = كل ما يعيق وصول الرسالة، سواء كان صوتا أو بصريا.", "EX": [["Donnez une définition du «bruit» d'après le texte.", "On désigne par «bruit» tout ce qui affecte à des degrés divers la transmission du message."], ["D'où peut provenir le bruit ?", "Du canal, de l'émetteur ou du récepteur, du message, ou du code."]], "n": 8, "s": "f", "k": "f1"}, {"m": 1, "i": "🎼", "t": "Le poème : «Dans ma maison» (Prévert) et «Je voyage bien peu» (Cocteau)", "B": [["Prévert, Paroles (1949)", ["Langue familière, absence de ponctuation, jeux de mots (champ sémantique de «bête», «gai comme un pinson»)", "Champ lexical des animaux (âne, pinson, dromadaire) rapprochant l'homme de l'animal", "Le poème critique la bêtise des habitudes et des noms que les hommes donnent aux choses"]], ["Cocteau, Plain-Chant (1923)", ["Poème en strophes sur des villes (Londres, Venise, Bruxelles, Rome, Alger) : le poète ne se sent bien nulle part sauf «en tes bras»", "Comparaisons dans les strophes 2 et 3 (Londres «cœur de charbon», Alger qui «sent la chèvre et la fleur de jasmin»)"]], ["Outils d'analyse", ["Vers, strophe, pieds (syllabes)", "Rimes suivies ou croisées", "Allitération (répétition d'un son consonantique), assonance (son vocalique)"]]], "K": "Pour analyser un poème : vers, strophes, rimes, sonorités et comparaisons.", "M": ["Compter les pieds (syllabes) de chaque vers", "Rimes suivies : AABB ; croisées : ABAB"], "X": "في الشعر: عدّ المقاطع، انظر القافية (متتابعة/متقاطعة)، والجناس الصوتي، والتشبيهات.", "EX": [["Différence entre allitération et assonance ?", "L'allitération répète un son consonantique (ex. «pinson pinson pinson»),